 ELSE
 IF EXISTS(SELECT 1 FROM customer WHERE kode_customer=CONVERT(X'494d502d4b53562d4e4f54322d4c2d3135' USING utf8mb4) COLLATE utf8mb4_unicode_ci OR (id_kavling=v_unit AND stt_arsip=0)) OR EXISTS(SELECT 1 FROM pengajuan_hold WHERE id_kavling=v_unit AND stt_reg IN (1,2)) OR EXISTS(SELECT 1 FROM kavling_peta WHERE id=v_unit AND COALESCE(id_customer,0)<>0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unit L-15 sudah digunakan; transaksi dibatalkan'; END IF;
